script:
log("_________________ Get Work Efforts Consolidated Data _________________")

# Получаем параметры
fd = frappe.form_dict
project = fd.get("project")
view_options = fd.get("view_options", "Прогноз и факт")

log(f"Загрузка данных для проекта: {project}, view_options: {view_options}")

# Своя простая функция для преобразования в float
def to_float(value):
    try:
        return float(value or 0)
    except:
        return 0.0

# 1. Получаем все задачи проекта одним запросом (с правильным порядком) через frappe.qb
Task = frappe.qb.DocType("Task")

tasks_query = (
    frappe.qb.from_(Task)
    .select(
        Task.name.as_("value"),
        Task.subject,
        Task.is_group.as_("expandable"),
        Task.parent_task,
        Task.type,
        Task.status,
        Task.custom_linked_issue,
        Task.color,
        Task.exp_start_date,   # ← добавить
        Task.exp_end_date,      # ← добавить
        Task.custom_planned_start_date,   # ← добавить
        Task.custom_planned_end_date,     # ← добавить
        Task.act_start_date,    # ← добавить
        Task.act_end_date       # ← добавить
    )
    .where(Task.project == project)
    .where(Task.docstatus < 2)
    .where(Task.is_milestone == 0)
    .orderby(Task.parent_task)
    .orderby(Task.exp_start_date)
    .orderby(Task.exp_end_date)
)

tasks = tasks_query.run(as_dict=True)

# Добавляем поле indent отдельно
for task in tasks:
    task['indent'] = 0
log(f"Загружено задач: {len(tasks)}")

# Создаем словарь для быстрого доступа к задачам по имени
task_dict = {task['value']: task for task in tasks}

# Создаем словарь дочерних задач
child_map = {}
for task in tasks:
    parent = task['parent_task'] or ''
    if parent not in child_map:
        child_map[parent] = []
    child_map[parent].append(task['value'])

# Функция для установки indent и создания иерархического списка
def build_hierarchy(parent_id, level, result_list):
    if parent_id in child_map:
        children = child_map[parent_id]
        for child_id in children:
            if child_id in task_dict:
                task = task_dict[child_id]
                task['indent'] = level
                result_list.append(task)
                # Рекурсивно добавляем детей
                build_hierarchy(child_id, level + 1, result_list)

# Создаем иерархически упорядоченный список
hierarchical_tasks = []
# Начинаем с корневых задач (без parent_task)
if '' in child_map:
    root_tasks = child_map['']
    for root_id in root_tasks:
        if root_id in task_dict:
            task = task_dict[root_id]
            task['indent'] = 0
            hierarchical_tasks.append(task)
            # Добавляем дочерние задачи
            build_hierarchy(root_id, 1, hierarchical_tasks)

# Теперь hierarchical_tasks содержит задачи в правильном иерархическом порядке
tasks = hierarchical_tasks

# 2. Получаем все Project Work Efforts с дочерними таблицами через frappe.qb
PWE = frappe.qb.DocType("Project Work Efforts")
PWEA = frappe.qb.DocType("Project Work Efforts Amount")

pwe_query = (
    frappe.qb.from_(PWE)
    .left_join(PWEA)
    .on(PWEA.parent == PWE.name)
    .select(
        PWE.name,
        PWE.pwe_task,
        PWE.pwe_project_role,
        PWEA.pwea_year,
        PWEA.pwea_month,
        PWEA.pwea_plan,
        PWEA.pwea_expected
    )
    .where(PWE.pwe_project == project)
    .orderby(PWE.pwe_task, PWE.pwe_project_role)
)

pwe_list = pwe_query.run(as_dict=True)
log(f"Загружено записей Project Work Efforts: {len(pwe_list)}")

# Группируем по задаче и роли
pwe_grouped = {}
for row in pwe_list:
    key = (row['pwe_task'], row['pwe_project_role'] or '')
    if key not in pwe_grouped:
        pwe_grouped[key] = {
            'task': row['pwe_task'],
            'role': row['pwe_project_role'],
            'plan_data': {},
            'forecast_data': {}
        }
    
    if row['pwea_year'] and row['pwea_month']:
        # !!! ИСПРАВЛЕНИЕ: преобразуем месяц в число без ведущего нуля
        month = str(int(row['pwea_month']))  # "08" -> "8", "12" -> "12"
        period_key = f"{row['pwea_year']}_{month}"
        pwe_grouped[key]['plan_data'][period_key] = to_float(row['pwea_plan'])
        pwe_grouped[key]['forecast_data'][period_key] = to_float(row['pwea_expected'])

# 3. Получаем все фактические данные из User Timesheet Position через frappe.qb
UTP = frappe.qb.DocType("User Timesheet Position")

ts_query = (
    frappe.qb.from_(UTP)
    .select(
        UTP.document_name.as_("task"),
        UTP.project_role,
        UTP.period,
        UTP.all_hours,
        UTP.name
    )
    .where(UTP.project == project)
    .where(UTP.status == "Согласовано")
    .where(UTP.document_type == "Task")
)

ts_raw_data = ts_query.run(as_dict=True)
log(f"Загружено сырых записей User Timesheet Position: {len(ts_raw_data)}")

# Группируем фактические данные в Python
fact_grouped = {}
for row in ts_raw_data:
    if row['period']:
        parts = row['period'].split('-')
        if len(parts) >= 2:
            year = parts[0]
            month = str(int(parts[1]))  # "08" -> "8", "12" -> "12"
            period_key = f"{year}_{month}"
            
            key = (row['task'], row['project_role'] or '')
            if key not in fact_grouped:
                fact_grouped[key] = {
                    'task': row['task'],
                    'role': row['project_role'],
                    'fact_data': {},
                    'fact_utps': {}
                }
            
            # Суммируем часы
            current_value = fact_grouped[key]['fact_data'].get(period_key, 0)
            fact_grouped[key]['fact_data'][period_key] = current_value + to_float(row['all_hours'])
            
            # Собираем имена UTP
            if period_key not in fact_grouped[key]['fact_utps']:
                fact_grouped[key]['fact_utps'][period_key] = []
            fact_grouped[key]['fact_utps'][period_key].append(row['name'])

# 4. Объединяем все данные
aggregated_tasks = {}
for task in tasks:
    task_id = task['value']
    aggregated_tasks[task_id] = {
        **task,
        'role_data': []
    }

# Сначала добавляем данные из Project Work Efforts
for (task_id, role), data in pwe_grouped.items():
    if task_id in aggregated_tasks:
        role_entry = {
            'role': role
        }
        
        # Добавляем плановые данные
        for period_key, value in data['plan_data'].items():
            role_entry[f'plan_{period_key}'] = value
        
        # Добавляем прогнозные данные
        for period_key, value in data['forecast_data'].items():
            role_entry[f'forecast_{period_key}'] = value
        
        aggregated_tasks[task_id]['role_data'].append(role_entry)

# Затем добавляем/обновляем фактические данные
for (task_id, role), data in fact_grouped.items():
    if task_id in aggregated_tasks:
        # Ищем существующую запись для роли
        role_entry = None
        for entry in aggregated_tasks[task_id]['role_data']:
            if entry['role'] == role:
                role_entry = entry
                break
        
        if not role_entry:
            role_entry = {'role': role}
            aggregated_tasks[task_id]['role_data'].append(role_entry)
        
        # Добавляем фактические данные
        for period_key, hours in data['fact_data'].items():
            role_entry[f'fact_{period_key}'] = hours
        
        # Добавляем UTP ссылки
        for period_key, utps in data['fact_utps'].items():
            role_entry[f'fact_utps_{period_key}'] = utps

# Удаляем пустые записи ролей
for task_id in aggregated_tasks:
    aggregated_tasks[task_id]['role_data'] = [
        r for r in aggregated_tasks[task_id]['role_data'] 
        if r.get('role') and r['role'].strip()
    ]

# 5. Применяем rollup фактических данных (оптимизированная версия)
# Создаем копию aggregated_tasks для сохранения иерархии
tasks_for_rollup = list(aggregated_tasks.values())

# Сортируем задачи по уровню вложенности (от самых глубоких к корневым)
tasks_for_rollup.sort(key=lambda x: x.get('indent', 0), reverse=True)

for child in tasks_for_rollup:
    parent_id = child.get('parent_task')
    
    if parent_id and parent_id in aggregated_tasks:
        parent = aggregated_tasks[parent_id]
        
        # Суммируем фактические данные по ролям
        for role_entry in child.get('role_data', []):
            role = role_entry['role']
            
            # Находим или создаем запись роли в родительской задаче
            parent_role_entry = None
            for pre in parent.get('role_data', []):
                if pre['role'] == role:
                    parent_role_entry = pre
                    break
            
            if not parent_role_entry:
                parent_role_entry = {'role': role}
                if 'role_data' not in parent:
                    parent['role_data'] = []
                parent['role_data'].append(parent_role_entry)
            
            # Суммируем все фактические данные
            for key in list(role_entry.keys()):
                if key.startswith('fact_') and not key.startswith('fact_utps'):
                    current_value = to_float(role_entry.get(key, 0))
                    parent_value = to_float(parent_role_entry.get(key, 0))
                    parent_role_entry[key] = parent_value + current_value
                
                # Объединяем UTP ссылки
                elif key.startswith('fact_utps_'):
                    child_utps = role_entry.get(key, [])
                    parent_utps = parent_role_entry.get(key, [])
                    parent_role_entry[key] = parent_utps + child_utps

log(f"Обработано агрегированных задач: {len(aggregated_tasks)}")

# Возвращаем результат в иерархическом порядке
# Собираем задачи обратно в иерархический список
result_list = []
if '' in child_map:
    root_tasks = child_map['']
    for root_id in root_tasks:
        if root_id in aggregated_tasks:
            result_list.append(aggregated_tasks[root_id])
            # Рекурсивно добавляем детей
            def add_children(parent_id):
                if parent_id in child_map:
                    for child_id in child_map[parent_id]:
                        if child_id in aggregated_tasks:
                            result_list.append(aggregated_tasks[child_id])
                            add_children(child_id)
            
            add_children(root_id)

frappe.response["message"] = result_list

