def perf_log(message):
    line = "[PWR V2 PERF] " + str(message)
    PERF_TRACE.append(line)
    log(line)

def perf_start(label):
    perf_log("START " + label)
    return frappe.utils.now_datetime()

def perf_end(label, started_at, extra=""):
    finished_at = frappe.utils.now_datetime()
    elapsed_ms = (finished_at - started_at).total_seconds() * 1000
    suffix = ""
    if extra:
        suffix = " | " + str(extra)
    perf_log("END " + label + ": " + str(int(elapsed_ms)) + " ms" + suffix)
    return elapsed_ms

def pwr_v2_assignment_query_base(PWA, Task, assignment_date_to_lower_bound, display_end, user, project, user_group, user_totals_sql_paged):
    q = frappe.qb.from_(PWA).left_join(Task).on(PWA.task == Task.name)
    if user_group and user_totals_sql_paged:
        UGM = frappe.qb.DocType("User Group Member")
        q = q.inner_join(UGM).on((UGM.parent == user_group) & (UGM.user == PWA.user))
    q = (
        q.where(PWA.user.isnotnull())
        .where(PWA.task.isnotnull())
        .where(Task.project.isnotnull())
        .where(PWA.date_from.isnotnull())
        .where(PWA.date_to >= assignment_date_to_lower_bound)
        .where(PWA.date_from <= display_end)
    )
    if user:
        q = q.where(PWA.user == user)
    if project:
        q = q.where(Task.project == project)
    return q

def build_date_to_period_key(periods, view_type):
    """ISS-2026-00865: O(1) date -> period lookup without changing period payload."""
    result = {}
    for period in periods:
        if view_type == 'daily':
            result[period['date']] = period['key']
        else:
            current_date = frappe.utils.getdate(period['start_date'])
            end_date = frappe.utils.getdate(period['end_date'])
            while current_date <= end_date:
                result[str(current_date)] = period['key']
                current_date = frappe.utils.add_days(current_date, 1)
    return result

def get_visible_window(periods, view_type):
    if not periods:
        today_obj = frappe.utils.getdate(frappe.utils.nowdate())
        return today_obj, today_obj
    if view_type == 'daily':
        return frappe.utils.getdate(periods[0]['date']), frappe.utils.getdate(periods[-1]['date'])
    return frappe.utils.getdate(periods[0]['start_date']), frappe.utils.getdate(periods[-1]['end_date'])

def find_period_key(date_str):
    global period_lookup_iterations
    period_lookup_iterations = period_lookup_iterations + 1
    return date_to_period_key.get(date_str)

