                working_hours_overrides[row.ref_name] = {}
            if row.wht_date:
                working_hours_overrides[row.ref_name][str(row.wht_date)] = float(row.wht_hours or 0)

    # 3.2 Holiday Lists
    holiday_lists_cache = {}
    # ISS-2026-00865: дополнительный set-cache только для быстрого lookup;
    # response по-прежнему использует списки holiday_lists_cache.
    holiday_date_sets = {}
    all_holiday_lists = {}

    # Собираем все holiday lists
    for project in projects_data.values():
        if project.get('holiday_list'):
            all_holiday_lists[project['holiday_list']] = True

    for user in users_data.values():
        if user.get('wholiday_list'):
            all_holiday_lists[user['wholiday_list']] = True

    if all_holiday_lists:
        holiday_list = list(all_holiday_lists.keys())
        perf_section_start = perf_start("SQL holidays")
        holidays = frappe.qb.get_query(
            "Holiday",
            fields=["parent as list_name", "holiday_date", "description", "weekly_off"],
            filters=[
                ["parent", "in", holiday_list],
                ["parentfield", "=", "holidays"],
                ["parenttype", "=", "Holiday List"],
            ],
        ).run(as_dict=True)
        perf_end("SQL holidays", perf_section_start, "holiday_lists=" + str(len(holiday_list)) + ", rows=" + str(len(holidays)))
        for row in holidays:
            if row.list_name not in holiday_lists_cache:
                holiday_lists_cache[row.list_name] = []
                holiday_date_sets[row.list_name] = {}

            holiday_item = {
                'date': str(row.holiday_date),
                'description': row.description,
                'weekly_off': row.weekly_off
            }
            holiday_lists_cache[row.list_name].append(holiday_item)
            holiday_date_sets[row.list_name][str(row.holiday_date)] = True

    # 3.3 Отсутствия
    user_absences = {}
    if users_list:
        today = frappe.utils.nowdate()
        perf_section_start = perf_start("SQL absences")
        absences = frappe.qb.get_query(
            "Application For Leave",
            fields=[
                "lauser",
                "alfrom_date",
                "alto_date",
                "altype_of_leave",
                "alfrom_hours",
                "alto_hours",
            ],
            filters=[
                ["lauser", "in", users_list],
                ["status", "=", "Согласовано"],
                ["alfrom_date", "is", "set"],
                ["alto_date", "is", "set"],
                ["alto_date", ">=", today],
            ],
        ).run(as_dict=True)
        perf_end("SQL absences", perf_section_start, "users=" + str(len(users_list)) + ", rows=" + str(len(absences)))
        for absence in absences:
            user_email = absence.lauser
            if user_email not in user_absences:
                user_absences[user_email] = []

            absence_item = {
                'from_date': absence.alfrom_date,
                'to_date': absence.alto_date,
                'type': absence.altype_of_leave,
                'alfrom_hours': absence.alfrom_hours,
                'alto_hours': absence.alto_hours
            }
            user_absences[user_email].append(absence_item)

    # 3.4 Плановые часы (Project Work Efforts)
    monthly_plan_cache = {}
    # ISS-2026-00865: раньше здесь был N+1, отдельный SQL на каждую пару task+role.
    # Для сохранения результата ключ cache остается тем же: task_role_year_month.
    task_role_pairs = {}
    tasks_set = {}
    roles_set = {}
    for assignment in assignments:
        if assignment.get('task') and assignment.get('role'):
            pair_key = assignment['task'] + "\n" + assignment['role']
            task_role_pairs[pair_key] = True
            tasks_set[assignment['task']] = True
            roles_set[assignment['role']] = True

    if task_role_pairs:
        task_list = list(tasks_set.keys())
        role_list = list(roles_set.keys())
        perf_section_start = perf_start("SQL project work efforts batch")
        PWE = frappe.qb.DocType("Project Work Efforts")
        PWEA = frappe.qb.DocType("Project Work Efforts Amount")
        plans = (
            frappe.qb.from_(PWE)
            .inner_join(PWEA)
            .on(PWEA.parent == PWE.name)
            .select(
                PWE.pwe_task.as_("task"),
                PWE.pwe_project_role.as_("role"),
                PWEA.pwea_year.as_("year"),
                PWEA.pwea_month.as_("month"),
                PWEA.pwea_plan.as_("plan_hours"),
            )
            .where(PWE.pwe_task.isin(task_list))
            .where(PWE.pwe_project_role.isin(role_list))
            .where(PWEA.pwea_plan > 0)
        ).run(as_dict=True)
        for plan in plans:
            key = plan['task'] + "_" + plan['role'] + "_" + str(plan['year']) + "_" + str(plan['month'])
            monthly_plan_cache[key] = float(plan['plan_hours'] or 0)
        perf_end("SQL project work efforts batch", perf_section_start, "task_roles=" + str(len(task_role_pairs)) + ", tasks=" + str(len(task_list)) + ", roles=" + str(len(role_list)) + ", rows=" + str(len(plans)) + ", cache=" + str(len(monthly_plan_cache)))
    else:
        perf_log("SKIP SQL project work efforts batch | task_roles=0")

    # ========== 4. ГЕНЕРАЦИЯ ПЕРИОДОВ (ИСПРАВЛЕННАЯ) ==========

    perf_section_start = perf_start("Generate periods")
    periods = []
    today = frappe.utils.nowdate()
    current_date_obj = frappe.utils.getdate(today)

    if view_type == 'daily':
        days_count = 90
        if period_range == 'half_year':
            days_count = 180
        elif period_range == 'year':
            days_count = 365

        for i in range(days_count):
            date_str = frappe.utils.add_days(today, i)
            date_obj = frappe.utils.getdate(date_str)
            period_item = {
                'key': 'workload_' + date_str,
                'date': date_str,
                'year': date_obj.year,
                'month': date_obj.month,
                'day': date_obj.day,
                'weekday': date_obj.weekday()
            }
            periods.append(period_item)

    elif view_type == 'weekly':
        weeks_count = 13
        if period_range == 'half_year':
            weeks_count = 26
        elif period_range == 'year':
            weeks_count = 52

        week_start = frappe.utils.add_days(today, -current_date_obj.weekday())

        for i in range(weeks_count):
            week_start_date = frappe.utils.add_days(week_start, i * 7)
            week_end_date = frappe.utils.add_days(week_start_date, 6)
            week_start_obj = frappe.utils.getdate(week_start_date)

            period_item = {
                'key': 'workload_' + str(week_start_obj.year) + '_week_' + str(i+1),
                'year': week_start_obj.year,
                'week': i + 1,
                'start_date': str(week_start_date),
                'end_date': str(week_end_date)
            }
            periods.append(period_item)

    else:  # monthly (ИСПРАВЛЕНО - добавляем year и month)
        months_count = 3
        if period_range == 'half_year':
            months_count = 6
        elif period_range == 'year':
            months_count = 12

        for i in range(months_count):
            # Берем текущий месяц и добавляем i месяцев
            total_month = current_date_obj.month + i
            year = current_date_obj.year
            month = total_month

            # Корректируем год и месяц если вышли за пределы
            if total_month > 12:
                year = year + 1
                month = total_month - 12

            month_str = str(month)
            if len(month_str) == 1:
                month_str = '0' + month_str

            start_date = frappe.utils.get_first_day(str(year) + '-' + month_str + '-01')
            end_date = frappe.utils.get_last_day(start_date)

            period_item = {
                'key': 'workload_' + str(year) + '_' + str(month),
                'year': year,
                'month': month,
                'start_date': str(start_date),
                'end_date': str(end_date)
            }
            periods.append(period_item)

    log("Generated " + str(len(periods)) + " periods for view_type=" + view_type + ", range=" + period_range)
    if periods:
        log("First period: " + str(periods[0]))
    perf_end("Generate periods", perf_section_start, "periods=" + str(len(periods)))
    # ISS-2026-00865: один раз строим lookup, чтобы не перебирать periods в горячих циклах.
    perf_section_start = perf_start("Build date_to_period_key")
    date_to_period_key = build_date_to_period_key(periods, view_type)
    perf_end("Build date_to_period_key", perf_section_start, "dates=" + str(len(date_to_period_key)))

    # ========== 5. ПРЕДВАРИТЕЛЬНЫЕ ВЫЧИСЛЕНИЯ ==========

    # 5.1 Кэш рабочих часов пользователей по дням
    perf_section_start = perf_start("Precompute user daily hours")
    user_daily_hours = {}
    user_daily_hours_dates_count = 0
    for user_email in users_list:
        user_data = users_data.get(user_email, {})
        base_hours = 8.0
        if user_data.get('hours_on_date'):
            base_hours = float(user_data['hours_on_date'])

        working_hours_ref = user_data.get('tt_working_hours_on_date')

        hours_dict = {}
        # Предвычисляем часы для всех дат во всех периодах
        for period in periods:
            if view_type == 'daily':
                date_str = period['date']
                hours_on_date = base_hours

                if working_hours_ref and working_hours_ref in working_hours_overrides:
                    override_dict = working_hours_overrides[working_hours_ref]
                    if date_str in override_dict:
                        hours_on_date = override_dict[date_str]

                hours_dict[date_str] = hours_on_date
                user_daily_hours_dates_count = user_daily_hours_dates_count + 1
            else:
                # Для недель/месяцев вычисляем все даты в диапазоне
                start_date = frappe.utils.getdate(period['start_date'])
                end_date = frappe.utils.getdate(period['end_date'])
                current_date = start_date
                while current_date <= end_date:
                    date_str = str(current_date)
                    hours_on_date = base_hours

                    if working_hours_ref and working_hours_ref in working_hours_overrides:
                        override_dict = working_hours_overrides[working_hours_ref]
                        if date_str in override_dict:
                            hours_on_date = override_dict[date_str]

                    hours_dict[date_str] = hours_on_date
                    user_daily_hours_dates_count = user_daily_hours_dates_count + 1
                    current_date = frappe.utils.add_days(current_date, 1)

        user_daily_hours[user_email] = hours_dict
    perf_end("Precompute user daily hours", perf_section_start, "users=" + str(len(users_list)) + ", date_entries=" + str(user_daily_hours_dates_count))

    # 5.2 Функция проверки рабочего дня (аналогичная оригинальной)
    working_day_cache = {}

    def is_working_day_cached(date_str, user_email, project_name):
        """Кэшированная проверка рабочего дня по оригинальной логике"""
        cache_key = date_str + "_" + user_email + "_" + project_name

        if cache_key in working_day_cache:
            return working_day_cache[cache_key]

        # Проверка праздников проекта
        project_data = projects_data.get(project_name, {})
        project_holiday_list = project_data.get('holiday_list')
        if project_holiday_list and project_holiday_list in holiday_date_sets:
            if date_str in holiday_date_sets[project_holiday_list]:
                working_day_cache[cache_key] = False
                return False

        # Проверка праздников пользователя
        user_data = users_data.get(user_email, {})
        user_holiday_list = user_data.get('wholiday_list')
        if user_holiday_list and user_holiday_list in holiday_date_sets:
            if date_str in holiday_date_sets[user_holiday_list]:
                working_day_cache[cache_key] = False
                return False

        # Проверка отсутствий (оригинальная логика)
        if user_email in user_absences:
            user_hours_dict = user_daily_hours.get(user_email, {})
            user_hours = user_hours_dict.get(date_str, 8.0)
            target_date = frappe.utils.getdate(date_str)

            user_absence_list = user_absences[user_email]
            for absence in user_absence_list:
                if not (absence['from_date'] and absence['to_date']):
                    continue

                from_date = frappe.utils.getdate(absence['from_date'])
                to_date = frappe.utils.getdate(absence['to_date'])

                if from_date <= target_date and target_date <= to_date:
                    absence_hours = 0.0
                    if target_date == from_date and absence.get('alfrom_hours'):
                        absence_hours = float(absence['alfrom_hours'])
                    elif target_date == to_date and absence.get('alto_hours'):
                        absence_hours = float(absence['alto_hours'])
                    else:
                        absence_hours = user_hours

                    if absence_hours >= user_hours:
                        working_day_cache[cache_key] = False
                        return False

        working_day_cache[cache_key] = True
        return True

    # 5.3 Функция получения часов отсутствия (оригинальная)
    def get_absence_hours(date_str, user_email):
        """Получение часов отсутствия на конкретную дату по оригинальной логике"""
        if user_email not in user_absences:
            return 0.0

        user_hours_dict = user_daily_hours.get(user_email, {})
        user_hours = user_hours_dict.get(date_str, 8.0)
        target_date = frappe.utils.getdate(date_str)

        user_absence_list = user_absences[user_email]
        for absence in user_absence_list:
            if not (absence['from_date'] and absence['to_date']):
                continue

            from_date = frappe.utils.getdate(absence['from_date'])
            to_date = frappe.utils.getdate(absence['to_date'])

            if from_date <= target_date and target_date <= to_date:
                if target_date == from_date and absence.get('alfrom_hours'):
                    return float(absence['alfrom_hours'])
                elif target_date == to_date and absence.get('alto_hours'):
                    return float(absence['alto_hours'])
                else:
                    return user_hours

        return 0.0

    # ========== 6. РАСЧЕТ НАГРУЗКИ ПО ОРИГИНАЛЬНОЙ ЛОГИКЕ ==========

    log("Starting workload calculation with original logic...")
    perf_section_start = perf_start("Calculate workload original logic")
    start_time = frappe.utils.now_datetime()

    # Результаты: для user_totals считаем напрямую user -> period_key -> hours,
    # для user_projects сохраняем детализацию user -> project -> period_key -> hours.
    direct_user_totals = user_totals_sql_paged
    results = {}
    assignment_calculations = 0
    workload_type_counts = {}
    date_loop_iterations = 0
    period_lookup_iterations = 0
    month_working_day_iterations = 0

    # Глобальный кэш рабочих дней в месяце
    month_working_days_cache = {}

    # ОПТИМИЗАЦИЯ: Предварительно группируем назначения по пользователям и проектам
    assignments_by_user_project = {}
    for assignment in assignments:
        user_email = assignment['user']
        project_name = assignment['project_name']

        if user_email not in assignments_by_user_project:
            assignments_by_user_project[user_email] = {}

        if project_name not in assignments_by_user_project[user_email]:
            assignments_by_user_project[user_email][project_name] = []

        assignments_by_user_project[user_email][project_name].append(assignment)

    # Обрабатываем каждую комбинацию пользователь-проект
    user_emails = list(assignments_by_user_project.keys())
    for user_email in user_emails:
        user_projects = assignments_by_user_project[user_email]
        project_names = list(user_projects.keys())

        for project_name in project_names:
            user_assignments = user_projects[project_name]

            # Инициализируем структуру результатов
            if user_email not in results:
                results[user_email] = {}
                if direct_user_totals:
                    for p in periods:
                        results[user_email][p['key']] = 0.0

            if not direct_user_totals and project_name not in results[user_email]:
                results[user_email][project_name] = {}
                for p in periods:
                    results[user_email][project_name][p['key']] = 0.0

            # Обрабатываем все назначения пользователя на этом проекте
            for assignment in user_assignments:
                workload_label = assignment.get('workload') or 'Unknown'
                workload_type_counts[workload_label] = workload_type_counts.get(workload_label, 0) + 1
                date_from = frappe.utils.getdate(assignment['date_from'])
                date_to = frappe.utils.getdate(assignment['date_to'])

                # Тип 1: В рабочих часах (ОРИГИНАЛЬНАЯ ЛОГИКА)
                if assignment['workload'] == 'В рабочих часах':
                    total_assignment_hours = 0.0
                    if assignment['wl_value']:
                        total_assignment_hours = float(assignment['wl_value'])

                    # ISS-2026-00865: для "В рабочих часах" сохраняем оригинальный знаменатель
                    # по полному диапазону назначения. Если обрезать его видимым окном,
                    # итоговые часы в tree_data изменятся.
                    total_available_in_period = 0.0
                    date_available_hours = {}  # Кэшируем доступные часы по датам

                    current_date = date_from
                    while current_date <= date_to:
                        date_loop_iterations = date_loop_iterations + 1
                        date_str = str(current_date)

                        if is_working_day_cached(date_str, user_email, project_name):
                            day_base_hours_dict = user_daily_hours.get(user_email, {})
                            day_base_hours = day_base_hours_dict.get(date_str, 8.0)
                            absence_hours = get_absence_hours(date_str, user_email)
                            available_hours = day_base_hours - absence_hours
                            if available_hours < 0:
                                available_hours = 0.0

                            total_available_in_period = total_available_in_period + available_hours
                            date_available_hours[date_str] = available_hours
                            assignment_calculations = assignment_calculations + 1

                        current_date = frappe.utils.add_days(current_date, 1)

                    if total_available_in_period > 0:
                        # Распределяем нагрузку по датам
                        date_keys = list(date_available_hours.keys())
                        for date_str in date_keys:
                            available_hours_on_date = date_available_hours[date_str]
                            if available_hours_on_date > 0:
                                daily_ratio = available_hours_on_date / total_available_in_period
                                daily_hours = total_assignment_hours * daily_ratio

                                # ISS-2026-00865: быстрый lookup вместо вложенного перебора periods.
                                period_key = find_period_key(date_str)

                                if period_key:
                                    if direct_user_totals:
                                        current_value = results[user_email][period_key]
                                        results[user_email][period_key] = current_value + daily_hours
                                    else:
                                        current_value = results[user_email][project_name][period_key]
                                        results[user_email][project_name][period_key] = current_value + daily_hours

                # Тип 2: В % от фонда рабочих часов (ОРИГИНАЛЬНАЯ ЛОГИКА)
                elif assignment['workload'] == 'В % от фонда рабочих часов':
                    percentage_value = 0.0
                    if assignment['wl_value']:
                        percentage_value = float(assignment['wl_value']) / 100  # Делим на 100 сразу

                    current_date = date_from
                    while current_date <= date_to:
                        date_loop_iterations = date_loop_iterations + 1
                        date_str = str(current_date)

                        if is_working_day_cached(date_str, user_email, project_name):
                            day_base_hours_dict = user_daily_hours.get(user_email, {})
                            day_base_hours = day_base_hours_dict.get(date_str, 8.0)
                            absence_hours = get_absence_hours(date_str, user_email)
                            available_hours = day_base_hours - absence_hours
                            if available_hours < 0:
                                available_hours = 0.0

                            daily_load = percentage_value * available_hours
                            assignment_calculations = assignment_calculations + 1

                            # ISS-2026-00865: быстрый lookup вместо вложенного перебора periods.
                            period_key = find_period_key(date_str)

                            if period_key:
                                if direct_user_totals:
                                    current_value = results[user_email][period_key]
                                    results[user_email][period_key] = current_value + daily_load
                                else:
                                    current_value = results[user_email][project_name][period_key]
                                    results[user_email][project_name][period_key] = current_value + daily_load

                        current_date = frappe.utils.add_days(current_date, 1)

                # Тип 3: В % от трудоемкости задачи (ИСПРАВЛЕННАЯ PROD-ЛОГИКА)
                elif assignment['workload'] == 'В % от трудоемкости задачи':
                    percentage_value = 0.0
                    if assignment['wl_value']:
                        percentage_value = float(assignment['wl_value']) / 100  # Делим на 100 сразу

                    task = assignment['task']
                    role = assignment['role']

                    # ISS-2026-00865 / ISS-2026-00586: prod-версия считает плановую
                    # трудоемкость только по рабочим дням внутри диапазона назначения,
                    # а не по всем рабочим дням календарного месяца.
                    months_in_period = {}
                    current_date = date_from
                    while current_date <= date_to:
                        date_loop_iterations = date_loop_iterations + 1
                        year = current_date.year
                        month = current_date.month
                        month_key = str(year) + "_" + str(month)

                        if month_key not in months_in_period:
                            months_in_period[month_key] = {
                                'year': year,
                                'month': month,
                                'working_days': 0,
                                'dates': []
                            }

                        date_str = str(current_date)
                        months_in_period[month_key]['dates'].append(date_str)

                        if is_working_day_cached(date_str, user_email, project_name):
                            months_in_period[month_key]['working_days'] = months_in_period[month_key]['working_days'] + 1
                            month_working_day_iterations = month_working_day_iterations + 1

                        current_date = frappe.utils.add_days(current_date, 1)

                    for month_key, month_info in months_in_period.items():
                        year = month_info['year']
                        month = month_info['month']
                        plan_key = task + "_" + role + "_" + str(year) + "_" + str(month)

                        if plan_key in monthly_plan_cache:
                            monthly_plan_hours = monthly_plan_cache[plan_key]

                            if monthly_plan_hours > 0 and month_info['working_days'] > 0:
                                base_daily_hours = monthly_plan_hours / month_info['working_days']

                                for date_str in month_info['dates']:
                                    if is_working_day_cached(date_str, user_email, project_name):
                                        daily_load = percentage_value * base_daily_hours

                                        # ISS-2026-00865: быстрый lookup вместо вложенного перебора periods.
                                        period_key = find_period_key(date_str)

                                        if period_key:
                                            if direct_user_totals:
                                                current_value = results[user_email][period_key]
                                                results[user_email][period_key] = current_value + daily_load
                                            else:
                                                current_value = results[user_email][project_name][period_key]
                                                results[user_email][project_name][period_key] = current_value + daily_load
                                            assignment_calculations = assignment_calculations + 1

    end_time = frappe.utils.now_datetime()
    time_diff = end_time - start_time
    calculation_time = time_diff.total_seconds() * 1000

    log("Calculation completed in " + str(calculation_time) + " ms, " + str(assignment_calculations) + " date calculations")
    perf_end("Calculate workload original logic", perf_section_start, "assignments=" + str(len(assignments)) + ", direct_user_totals=" + str(direct_user_totals) + ", workload_types=" + str(workload_type_counts) + ", date_loop_iterations=" + str(date_loop_iterations) + ", period_lookup_iterations=" + str(period_lookup_iterations) + ", month_working_day_iterations=" + str(month_working_day_iterations) + ", working_day_cache_size=" + str(len(working_day_cache)))

    # ========== 7. ФОРМИРОВАНИЕ TREE DATA ==========

    perf_section_start = perf_start("Build tree_data response")
    tree_data = []
    user_emails_result = list(results.keys())
    user_emails_result.sort()
    return_user_rows = mode != 'user_projects'
    return_project_rows = mode != 'user_totals'

    for user_email in user_emails_result:
        projects_result = results[user_email]

        # Строка пользователя
        user_total = {}
        for p in periods:
            user_total[p['key']] = 0.0

        if direct_user_totals:
            period_keys = list(projects_result.keys())
            for period_key in period_keys:
                user_total[period_key] = projects_result[period_key]
            project_names_result = []
        else:
            # Суммируем нагрузку по всем проектам пользователя
            project_names_result = list(projects_result.keys())
            for project_name in project_names_result:
                period_hours = projects_result[project_name]
                period_keys = list(period_hours.keys())
                for period_key in period_keys:
                    hours = period_hours[period_key]
                    user_total[period_key] = user_total[period_key] + hours

        # Получаем данные пользователя
        user_info = users_data.get(user_email, {})
        if not user_info:
            # Если пользователь не найден в users_data, создаем базовую запись
            user_info = {
                'full_name': user_email,
                'user_image': None,
                'email': user_email,
                'name': user_email,
                'wholiday_list': None
            }

        # Создаем строку пользователя
        user_row = {
            'participant': user_email,
            'user_data': {
                'full_name': user_info.get('full_name') or user_email,
                'user_image': user_info.get('user_image'),
                'email': user_email,
                'name': user_email
            },
            'indent': 0,
            'expandable': direct_user_totals or len(projects_result) > 0,
            '_isUser': True,
            '_detailsLoaded': return_project_rows,
            '_email': user_email,
            '_workingHours': user_daily_hours.get(user_email, {}),
            '_absences': user_absences.get(user_email, []),
            '_userHolidays': holiday_lists_cache.get(user_info.get('wholiday_list', ''), [])
        }

        # Добавляем нагрузку по периодам
        user_total_sum = 0.0
        for period in periods:
            period_key = period['key']
            hours = user_total.get(period_key, 0.0)
            user_row[period_key] = "%.1f" % hours
            user_total_sum = user_total_sum + hours

        user_row['workload_total'] = "%.1f" % user_total_sum
        if return_user_rows:
            tree_data.append(user_row)

        # Строки проектов для этого пользователя
        project_names_result.sort()
        for project_name in project_names_result:
            if not return_project_rows:
                continue
            period_hours = projects_result[project_name]
            project_info = projects_data.get(project_name, {})
            if not project_info:
                # Если проект не найден в projects_data, создаем базовую запись
                project_info = {
                    'project_name': project_name,
                    'holiday_list': None
                }

            project_row = {
                'participant': user_email,
                'user_data': user_row['user_data'],
                'project': project_info.get('project_name') or project_name,
                'project_name': project_name,
                'indent': 1,
                'expandable': False,
                '_isProject': True,
                '_email': user_email,
                '_project': project_name,
                '_workingHours': user_daily_hours.get(user_email, {}),
                '_absences': user_absences.get(user_email, []),
                '_projectHolidays': holiday_lists_cache.get(project_info.get('holiday_list', ''), [])
            }

            project_total = 0.0
            for period in periods:
                period_key = period['key']
                hours = period_hours.get(period_key, 0.0)
                project_row[period_key] = "%.1f" % hours
                project_total = project_total + hours

            project_row['workload_total'] = "%.1f" % project_total
            tree_data.append(project_row)
    perf_end("Build tree_data response", perf_section_start, "mode=" + str(mode) + ", users=" + str(len(user_emails_result)) + ", rows=" + str(len(tree_data)))
    perf_end("TOTAL get_projects_workload_data_v2", PERF_TOTAL_START, "mode=" + str(mode) + ", tree_rows=" + str(len(tree_data)) + ", periods=" + str(len(periods)) + ", assignments=" + str(len(assignments)))
    frappe.log_error("\n".join(PERF_TRACE), "PWR V2 PERF get_projects_workload_data_v2")

    # ========== 8. ФИНАЛЬНЫЙ ОТВЕТ ==========

    frappe.response["message"] = {
        'tree_data': tree_data,
        'periods': periods,
        'users_count': len(users_list),
        'projects_count': len(projects_list),
        'assignments_count': len(assignments),
        'mode': mode,
        'limit': limit,
        'offset': offset,
        'next_offset': next_offset,
        'has_more': has_more,
        'total_users': total_users,
        'message': 'Data loaded successfully in ' + str(int(calculation_time)) + ' ms (CORRECTED LOGIC V2)',
        'performance': {
            'calculation_time_ms': calculation_time,
            'assignments': len(assignments),
            'date_calculations': assignment_calculations,
            'working_day_cache_size': len(working_day_cache),
            'trace': PERF_TRACE
        }
    }

except Exception as e:
    perf_end("TOTAL get_projects_workload_data_v2 FAILED", PERF_TOTAL_START, "error=" + str(e))
    frappe.log_error("\n".join(PERF_TRACE), "PWR V2 PERF get_projects_workload_data_v2 FAILED")
    log("Error in get_projects_workload_data: " + str(e))

    frappe.response["message"] = {
        'tree_data': [],
        'periods': [],
        'users_count': 0,
        'projects_count': 0,
        'assignments_count': 0,
        'mode': frappe.form_dict.get('mode', 'full'),
        'error': str(e),
        'message': 'Error loading data'
    }

# Флаг для включения/отключения детального логирования

ENABLE_DETAILED_LOG = True



def debug_log(message):

    """Логирует сообщение только если детальное логирование включено"""

    if ENABLE_DETAILED_LOG:

        log(message)



def get_tasks_forecast_and_workload_internal():

    """Получает все задачи с прогнозом (PWE) и нагрузкой (PWA)"""



    project = frappe.form_dict.get('project')

    periods = frappe.form_dict.get('periods')

    view_options = frappe.form_dict.get('view_options', 'Прогноз и факт')



    debug_log("=== STEP 1: PARAMETERS ===")

    debug_log(f"Project: {project}")

    debug_log(f"Periods received: {periods is not None}")

    debug_log(f"View options: {view_options}")



    if not project:

        frappe.response["message"] = {

            'tasks': [],

            'tasks_details': {},

            'error': 'No project specified'

        }

        return



    # ========== 1. ПОЛУЧАЕМ ПЕРИОДЫ ==========

    debug_log("=== STEP 2: GET PERIODS ===")



    if not periods or not isinstance(periods, list):

        debug_log("No periods provided, generating from project dates")



        Project = frappe.qb.DocType('Project')

        project_data = (

            frappe.qb.from_(Project)

            .select(Project.expected_start_date, Project.expected_end_date)

            .where(Project.name == project)

            .limit(1)

        ).run(as_dict=True)



        if project_data:

            project_data = project_data[0]



        if not project_data.get('expected_start_date'):

            frappe.response["message"] = {

                'tasks': [],

                'tasks_details': {},

                'error': 'Project start date not set'

            }

            return



        start = frappe.utils.getdate(project_data.get('expected_start_date'))

        end = frappe.utils.getdate(project_data.get('expected_end_date') or frappe.utils.add_months(start, 12))



        periods = []

        current = frappe.utils.getdate(f"{start.year}-{start.month:02d}-01")

        end_first = frappe.utils.getdate(f"{end.year}-{end.month:02d}-01")



        while current <= end_first:

            next_month = frappe.utils.add_months(current, 1)

            next_month_start = frappe.utils.getdate(f"{next_month.year}-{next_month.month:02d}-01")

            is_past = next_month_start <= frappe.utils.getdate(frappe.utils.nowdate())



            periods.append({

                'year': current.year,

                'month': current.month,

                'is_past': is_past

            })

            current = frappe.utils.add_months(current, 1)



        debug_log(f"Generated {len(periods)} periods")

    else:

        debug_log(f"Received {len(periods)} periods")



    # ========== ФИЛЬТРАЦИЯ ПЕРИОДОВ ПО view_options ==========

    debug_log("=== STEP 2.5: FILTER PERIODS BY view_options ===")



    periods_to_check = []

    if view_options == "Только факт":

        # Не проверяем ничего

        periods_to_check = []

    elif view_options == "Только прогноз":

        # Проверяем ВСЕ периоды

        periods_to_check = periods

    else:  # "Прогноз и факт"

        # Проверяем только текущий и будущие периоды

        periods_to_check = [p for p in periods if not p.get('is_past', False)]



    debug_log(f"  view_options: {view_options}")

    debug_log(f"  periods before filter: {len(periods)}")

    debug_log(f"  periods after filter: {len(periods_to_check)}")



    periods = periods_to_check



    if not periods:

        frappe.response["message"] = {

            'tasks': [],

            'tasks_details': {},

            'total_tasks': 0

        }

        return



    # ========== 2. ПОЛУЧАЕМ ПРОГНОЗНЫЕ ДАННЫЕ (PWE) ==========

    debug_log("=== STEP 3: GET FORECAST DATA (PWE) ===")



    PWE = frappe.qb.DocType('Project Work Efforts')

    PWEA = frappe.qb.DocType('Project Work Efforts Amount')



    pwe_query = (

        frappe.qb.from_(PWE)

        .left_join(PWEA)

        .on(PWEA.parent == PWE.name)

        .select(

            PWE.pwe_task.as_('task'),

            PWE.pwe_project_role.as_('role'),

            PWEA.pwea_year.as_('year'),

            PWEA.pwea_month.as_('month'),

            PWEA.pwea_expected.as_('forecast_hours')

        )

        .where(PWE.pwe_project == project)

        .where(PWEA.pwea_expected.isnotnull())

        .where(PWEA.pwea_expected > 0)

    )



    pwe_list = pwe_query.run(as_dict=True)

    debug_log(f"Raw PWE records found: {len(pwe_list)}")



    forecast_cache = {}

    for row in pwe_list:

        if row.get('year') and row.get('month'):

            month = int(row.get('month'))

            key = f"{row.get('task')}_{row.get('role')}_{row.get('year')}_{month}"

            forecast_cache[key] = float(row.get('forecast_hours', 0))



    debug_log(f"Forecast cache size: {len(forecast_cache)}")



    # ========== 3. ПОЛУЧАЕМ ВСЕ НАЗНАЧЕНИЯ (PWA) ==========

    debug_log("=== STEP 4: GET ASSIGNMENTS (PWA) ===")



    if periods:

        min_date = f"{periods[0]['year']}-{periods[0]['month']:02d}-01"

        max_date = frappe.utils.get_last_day(f"{periods[-1]['year']}-{periods[-1]['month']:02d}-01")

    else:

        min_date = "2000-01-01"

        max_date = "2100-12-31"



    debug_log(f"Date range for assignments: {min_date} to {max_date}")



    PWA = frappe.qb.DocType('Project Workload Assignment')

    Task = frappe.qb.DocType('Task')

    User = frappe.qb.DocType('User')

    Worker = frappe.qb.DocType('Worker')

    TimesheetTemplate = frappe.qb.DocType('Timesheet Template')



    assignments_query = (

        frappe.qb.from_(PWA)

        .inner_join(Task)

        .on(Task.name == PWA.task)

        .left_join(User)

        .on(User.name == PWA.user)

        .left_join(Worker)

        .on(Worker.wuser == PWA.user)

        .left_join(TimesheetTemplate)

        .on(TimesheetTemplate.name == Worker.wtimesheet_template)

        .select(

            PWA.name,

            PWA.task,

            Task.subject.as_('task_subject'),

            PWA.role,

            PWA.user,

            User.full_name.as_('user_full_name'),

            PWA.workload,

            PWA.wl_value,

            PWA.date_from,

            PWA.date_to,

            Worker.wholiday_list,

            Worker.wtimesheet_template,

            TimesheetTemplate.hours_on_date,

            TimesheetTemplate.tt_working_hours_on_date

        )

        .where(Task.project == project)

        .where(PWA.date_from.isnotnull())

        .where(PWA.date_to.isnotnull())

        .where(PWA.date_to >= min_date)

        .where(PWA.date_from <= max_date)

    )



    assignments = assignments_query.run(as_dict=True)

    debug_log(f"Assignments found: {len(assignments)}")



    if not assignments:

        debug_log("No assignments found")

        frappe.response["message"] = {

            'tasks': [],

            'tasks_details': {}

        }

        return



    # ========== 4. ПОЛУЧАЕМ ВСПОМОГАТЕЛЬНЫЕ ДАННЫЕ ==========

    debug_log("=== STEP 5: GET AUXILIARY DATA ===")



    # 4.1 Holiday lists

    Project = frappe.qb.DocType('Project')

    project_holiday_result = (

        frappe.qb.from_(Project)

        .select(Project.holiday_list)

        .where(Project.name == project)

        .limit(1)

    ).run(as_dict=True)

    project_holiday_list = project_holiday_result[0].get('holiday_list') if project_holiday_result else None

    debug_log(f"Project holiday list: {project_holiday_list}")



    all_holiday_lists = set()

    user_holiday_lists = {}



    if project_holiday_list:

        all_holiday_lists.add(project_holiday_list)



    for a in assignments:

        if a.get('wholiday_list'):

            all_holiday_lists.add(a.get('wholiday_list'))

            user_holiday_lists[a.get('user')] = a.get('wholiday_list')



    debug_log(f"Total unique holiday lists: {len(all_holiday_lists)}")



    # 4.2 Загружаем праздники

    holidays_cache = {}

    if all_holiday_lists:

        Holiday = frappe.qb.DocType('Holiday')

        holidays = (

            frappe.qb.from_(Holiday)

            .select(

                Holiday.parent.as_('list_name'),

                Holiday.holiday_date,

                Holiday.weekly_off

            )

            .where(Holiday.parent.isin(list(all_holiday_lists)))

        ).run(as_dict=True)

        debug_log(f"Total holiday records loaded: {len(holidays)}")



        for h in holidays:

            list_name = h.get('list_name')

            if list_name not in holidays_cache:

                holidays_cache[list_name] = {

                    'dates': set(),

                    'weekly_off_dates': set()

                }

            date_str = str(h.get('holiday_date'))

            holidays_cache[list_name]['dates'].add(date_str)

            if h.get('weekly_off'):

                holidays_cache[list_name]['weekly_off_dates'].add(date_str)



    # 4.3 Загружаем отсутствия

    users = list(set(a.get('user') for a in assignments if a.get('user')))

    debug_log(f"Unique users: {len(users)}")



    absences_cache = {}

    if users:

        ApplicationForLeave = frappe.qb.DocType('Application For Leave')

        absences = (

            frappe.qb.from_(ApplicationForLeave)

            .select(

                ApplicationForLeave.lauser.as_('user'),

                ApplicationForLeave.alfrom_date,

                ApplicationForLeave.alto_date,

                ApplicationForLeave.altype_of_leave,

                ApplicationForLeave.alfrom_hours,

                ApplicationForLeave.alto_hours

            )

            .where(ApplicationForLeave.lauser.isin(users))

            .where(ApplicationForLeave.status == 'Согласовано')

            .where(ApplicationForLeave.alfrom_date.isnotnull())

            .where(ApplicationForLeave.alto_date.isnotnull())

        ).run(as_dict=True)

        debug_log(f"Total absence records: {len(absences)}")



        for a in absences:

            user = a.get('user')

            if user not in absences_cache:

                absences_cache[user] = []

            absences_cache[user].append(a)



    # 4.4 Загружаем переопределения рабочих часов

    working_hours_overrides = {}

    template_refs = set(a.get('tt_working_hours_on_date') for a in assignments if a.get('tt_working_hours_on_date'))

    debug_log(f"Unique working hours templates: {len(template_refs)}")



    if template_refs:

        WorkingHoursTable = frappe.qb.DocType('Working Hours Table')

        overrides = (

            frappe.qb.from_(WorkingHoursTable)

            .select(

                WorkingHoursTable.parent.as_('ref_name'),

                WorkingHoursTable.wht_date,

                WorkingHoursTable.wht_hours

            )

            .where(WorkingHoursTable.parent.isin(list(template_refs)))

            .where(WorkingHoursTable.parentfield == 'hod_working_hours_table')

            .where(WorkingHoursTable.parenttype == 'Working Hours On Date')

        ).run(as_dict=True)

        debug_log(f"Working hours overrides: {len(overrides)}")



        for o in overrides:

            ref_name = o.get('ref_name')

            if ref_name not in working_hours_overrides:

                working_hours_overrides[ref_name] = {}

            if o.get('wht_date'):

                working_hours_overrides[ref_name][str(o.get('wht_date'))] = float(o.get('wht_hours') or 0)



    # 4.5 Базовая норма часов

    base_hours_by_user = {}

    for a in assignments:

        if a.get('user') and a.get('user') not in base_hours_by_user:

            base_hours_by_user[a.get('user')] = float(a.get('hours_on_date') or 8.0)

    debug_log(f"Base hours set for {len(base_hours_by_user)} users")



    # ========== 5. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ==========



    def is_working_day(date_str, user):

        if project_holiday_list and project_holiday_list in holidays_cache:

            hc = holidays_cache[project_holiday_list]

            if date_str in hc['dates'] and date_str not in hc['weekly_off_dates']:

                return False

        user_holiday_list = user_holiday_lists.get(user)

        if user_holiday_list and user_holiday_list in holidays_cache:

            hc = holidays_cache[user_holiday_list]

            if date_str in hc['dates'] and date_str not in hc['weekly_off_dates']:

                return False

        if user in absences_cache:

            date_obj = frappe.utils.getdate(date_str)

            for absence in absences_cache[user]:

                from_date = frappe.utils.getdate(absence.get('alfrom_date'))

                to_date = frappe.utils.getdate(absence.get('alto_date'))

                if from_date <= date_obj <= to_date:

                    if date_obj == from_date and absence.get('alfrom_hours'):

                        if float(absence.get('alfrom_hours')) >= 8:

                            return False

                    elif date_obj == to_date and absence.get('alto_hours'):

                        if float(absence.get('alto_hours')) >= 8:

                            return False

                    else:

                        return False

        return True



    def get_available_hours(date_str, user):

        if not is_working_day(date_str, user):

            return 0.0

        base_hours = base_hours_by_user.get(user, 8.0)

        for a in assignments:

            if a.get('user') == user and a.get('tt_working_hours_on_date'):

                overrides = working_hours_overrides.get(a.get('tt_working_hours_on_date'), {})

                if date_str in overrides:

                    base_hours = overrides[date_str]

                    break

        if user in absences_cache:

            date_obj = frappe.utils.getdate(date_str)

            for absence in absences_cache[user]:

                from_date = frappe.utils.getdate(absence.get('alfrom_date'))

                to_date = frappe.utils.getdate(absence.get('alto_date'))

                if from_date <= date_obj <= to_date:

                    if date_obj == from_date and absence.get('alfrom_hours'):

                        return max(0, base_hours - float(absence.get('alfrom_hours')))

                    elif date_obj == to_date and absence.get('alto_hours'):

                        return max(0, base_hours - float(absence.get('alto_hours')))

        return base_hours



    def get_working_days_in_period(assignment, period_start, period_end):

        calc_start = max(frappe.utils.getdate(assignment.get('date_from')), period_start)

        calc_end = min(frappe.utils.getdate(assignment.get('date_to')), period_end)

        if calc_start > calc_end:

            return 0

        working_days = 0

        current = calc_start

        while current <= calc_end:

            if is_working_day(str(current), assignment.get('user')):

                working_days += 1

            current = frappe.utils.add_days(current, 1)

        return working_days



    def calculate_effort_percentage_workload(assignment, period, forecast_hours):

        if not forecast_hours or forecast_hours <= 0:

            return 0

        percentage = float(assignment.get('wl_value') or 0) / 100

        period_start = frappe.utils.getdate(f"{period['year']}-{period['month']:02d}-01")

        period_end = frappe.utils.get_last_day(period_start)

        working_days = get_working_days_in_period(assignment, period_start, period_end)

        if working_days == 0:

            return 0

        base_daily = forecast_hours / working_days

        return percentage * base_daily * working_days



    # ========== 6. СБОР ВСЕХ ДАННЫХ ПО ЗАДАЧАМ ==========

    debug_log("=== STEP 6: COLLECT TASKS DATA ===")



    tasks_map = {}

    tasks_details = {}



    # СНАЧАЛА: собираем все прогнозы по задачам из forecast_cache

    debug_log("  Collecting forecasts from PWE...")

    for key, forecast_hours in forecast_cache.items():

        parts = key.split('_')

        if len(parts) >= 4:

            task = '_'.join(parts[:-3])

            role = parts[-3]

            year = int(parts[-2])

            month = int(parts[-1])



            if task not in tasks_map:

                tasks_map[task] = {

                    'task': task,

                    'task_subject': task,

                    'total_forecast': 0,

                    'total_assigned': 0

                }

            tasks_map[task]['total_forecast'] = tasks_map[task]['total_forecast'] + forecast_hours



            if task not in tasks_details:

                tasks_details[task] = {}

            if role not in tasks_details[task]:

                tasks_details[task][role] = {}

            period_key = f"{year}-{month}"

            tasks_details[task][role][period_key] = {

                'forecast_hours': forecast_hours,

                'users': {}

            }



            debug_log(f"    Added forecast for {task}/{role}/{period_key}: +{forecast_hours}")



    # Добавляем task_subject для задач

    for a in assignments:

        if a.get('task') in tasks_map and tasks_map[a.get('task')]['task_subject'] == a.get('task'):

            tasks_map[a.get('task')]['task_subject'] = a.get('task_subject') or a.get('task')



    # Затем: собираем нагрузку из PWA

    debug_log("  Collecting workload from PWA...")

    period_counter = 0

    task_role_counter = 0

    checked_counter = 0



    for period in periods:

        period_counter += 1

        period_start = frappe.utils.getdate(f"{period['year']}-{period['month']:02d}-01")

        period_end = frappe.utils.get_last_day(period_start)

        period_key = f"{period['year']}-{period['month']}"



        debug_log(f"Processing period {period_counter}/{len(periods)}: {period['year']}-{period['month']}")



        # Группируем назначения по (task, role)

        grouped = {}

        for a in assignments:

            assign_start = frappe.utils.getdate(a.get('date_from'))

            assign_end = frappe.utils.getdate(a.get('date_to'))

            if period_end >= assign_start and period_start <= assign_end:

                key = (a.get('task'), a.get('role') or '')

                if key not in grouped:

                    grouped[key] = []

                grouped[key].append(a)



        debug_log(f"  Task-role combinations in this period: {len(grouped)}")



        for (task, role), assigns in grouped.items():

            task_role_counter += 1



            forecast_key = f"{task}_{role}_{period['year']}_{period['month']}"

            forecast_hours = forecast_cache.get(forecast_key, 0)



            if task not in tasks_map:

                tasks_map[task] = {

                    'task': task,

                    'task_subject': assigns[0].get('task_subject') if assigns[0].get('task_subject') else task,

                    'total_forecast': 0,

                    'total_assigned': 0

                }



            # Добавляем прогноз (если его еще нет)

            if tasks_map[task]['total_forecast'] == 0 and forecast_hours > 0:

                tasks_map[task]['total_forecast'] = tasks_map[task]['total_forecast'] + forecast_hours



            period_assigned = 0



            for assignment in assigns:

                checked_counter += 1

                workload_type = assignment.get('workload')

                percentage = float(assignment.get('wl_value') or 0)



                # Инициализируем структуру

                if task not in tasks_details:

                    tasks_details[task] = {}

                if role not in tasks_details[task]:

                    tasks_details[task][role] = {}

                if period_key not in tasks_details[task][role]:

                    tasks_details[task][role][period_key] = {

                        'forecast_hours': forecast_hours,

                        'users': {}

                    }



                # Для типа "В % от трудоемкости задачи"

                if workload_type == 'В % от трудоемкости задачи':

                    if forecast_hours > 0:

                        assigned = calculate_effort_percentage_workload(assignment, period, forecast_hours)

                    else:

                        assigned = 0

                else:

                    assign_start = frappe.utils.getdate(assignment.get('date_from'))

                    assign_end = frappe.utils.getdate(assignment.get('date_to'))



                    # Общее количество рабочих дней в назначении

                    total_working_days = 0

                    current = assign_start

                    while current <= assign_end:

                        if is_working_day(str(current), assignment.get('user')):

                            total_working_days += 1

                        current = frappe.utils.add_days(current, 1)



                    # Количество рабочих дней в текущем периоде

                    period_working_days = 0

                    current = max(assign_start, period_start)

                    period_end_date = min(assign_end, period_end)

                    while current <= period_end_date:

                        if is_working_day(str(current), assignment.get('user')):

                            period_working_days += 1

                        current = frappe.utils.add_days(current, 1)



                    ratio = period_working_days / total_working_days if total_working_days > 0 else 0



                    if workload_type == 'В рабочих часах':

                        total_hours = float(assignment.get('wl_value') or 0)

                        assigned = total_hours * ratio

                    elif workload_type == 'В % от фонда рабочих часов':

                        percentage_value = float(assignment.get('wl_value') or 0) / 100

                        period_available = 0

                        current = max(assign_start, period_start)

                        while current <= min(assign_end, period_end):

                            if is_working_day(str(current), assignment.get('user')):

                                period_available += get_available_hours(str(current), assignment.get('user'))

                            current = frappe.utils.add_days(current, 1)

                        assigned = percentage_value * period_available

                    else:

                        continue



                if assigned > 0:

                    period_assigned = period_assigned + assigned



                    user_email = assignment.get('user')



                    if user_email not in tasks_details[task][role][period_key]['users']:

                        tasks_details[task][role][period_key]['users'][user_email] = {

                            'assigned_hours': 0,

                            'workload_type': workload_type,

                            'percentage': percentage

                        }



                    current_hours = tasks_details[task][role][period_key]['users'][user_email]['assigned_hours']

                    tasks_details[task][role][period_key]['users'][user_email]['assigned_hours'] = current_hours + assigned



            # Обновляем total_assigned

            if task not in tasks_map:

                tasks_map[task] = {

                    'task': task,

                    'task_subject': task,

                    'total_forecast': 0,

                    'total_assigned': 0

                }

            tasks_map[task]['total_assigned'] = tasks_map[task]['total_assigned'] + period_assigned



            debug_log(f"    Added workload for {task}/{role}/{period_key}: +{period_assigned} hours total")



    # ========== 7. ФОРМИРУЕМ ОТВЕТ ==========

    debug_log("=== STEP 7: RESULTS ===")

    debug_log(f"Total periods processed: {period_counter}")

    debug_log(f"Total task-role combinations processed: {task_role_counter}")

    debug_log(f"Total assignments calculations: {checked_counter}")

    debug_log(f"Total tasks with data: {len(tasks_map)}")



    tasks_aggregated = []

    for task_id, task_data in tasks_map.items():

        tasks_aggregated.append({

            'task': task_data['task'],

            'task_subject': task_data['task_subject'],

            'total_forecast': round(task_data['total_forecast'], 2),

            'total_assigned': round(task_data['total_assigned'], 2)

        })



    log(f"Tasks with forecast/workload: {len(tasks_aggregated)}")



    frappe.response["message"] = {

        'tasks': tasks_aggregated,

        'tasks_details': tasks_details,

        'total_tasks': len(tasks_aggregated)

    }



